from melite_models import Model, Variant, Cell, LoraRow, Genre, ClipType, Quant


class Detect(Model):
    id = 'auto-detect'
    genre = Genre.IMAGE
    label = 'Auto Detect'
    description = 'Auto Detect — automatically selects the best model and conditioning for a given input.'
    form = 'form_detect'
    defaults = dict(
            output_mode='segm',
            detect_mode='face',
            detection_threshold=0.35,
            sam_dilation=0,
            sam_threshold=0.93,
        )

    # the CASCADE GATE (image-edit rework 2026-09-05) — a weightless
    # tool / transport / preprocessor lane ships NATIVE as its single
    # quant (no weights matrix; the lane's own engine owns whatever
    # load it has).
    variants = (
        Variant(id='standard', label='Standard', route='auto-detect', cells=(
            Cell(quant=Quant.NATIVE, label='Native (weightless)', route='auto-detect'),
        )),
    )

